    // Reorder queue - matches Python reorder_queued_episodes function
    /// Rewrite a user's queue positions to `1..N` in the given order.
    ///
    /// Each item is `(episode_id, is_youtube)`. `is_youtube` disambiguates a podcast
    /// `EpisodeID` from a YouTube `VideoID` that share an integer, so only the
    /// intended row is repositioned. `None` preserves the legacy id-only match for
    /// older clients that don't send a type discriminator.
    pub async fn reorder_queue(
        &self,
        user_id: i32,
        items: Vec<(i32, Option<bool>)>,
    ) -> AppResult<()> {
        match self {
            DatabasePool::Postgres(pool) => {
                let mut tx = pool.begin().await?;

                for (index, (episode_id, is_youtube)) in items.iter().enumerate() {
                    let new_position = (index + 1) as i32;
                    match is_youtube {
                        Some(flag) => {
                            sqlx::query(
                                r#"UPDATE "EpisodeQueue" SET queueposition = $1
                                   WHERE episodeid = $2 AND userid = $3 AND is_youtube = $4"#
                            )
                            .bind(new_position)
                            .bind(episode_id)
                            .bind(user_id)
                            .bind(flag)
                            .execute(&mut *tx)
                            .await?;
                        }
                        None => {
                            sqlx::query(
                                r#"UPDATE "EpisodeQueue" SET queueposition = $1
                                   WHERE episodeid = $2 AND userid = $3"#
                            )
                            .bind(new_position)
                            .bind(episode_id)
                            .bind(user_id)
                            .execute(&mut *tx)
                            .await?;
                        }
                    }
                }

                tx.commit().await?;
                Ok(())
            }
            DatabasePool::MySQL(pool) => {
                let mut tx = pool.begin().await?;

                for (index, (episode_id, is_youtube)) in items.iter().enumerate() {
                    let new_position = (index + 1) as i32;
                    match is_youtube {
                        Some(flag) => {
                            sqlx::query(
                                "UPDATE EpisodeQueue SET QueuePosition = ?
                                 WHERE EpisodeID = ? AND UserID = ? AND is_youtube = ?"
                            )
                            .bind(new_position)
                            .bind(episode_id)
                            .bind(user_id)
                            .bind(flag)
                            .execute(&mut *tx)
                            .await?;
                        }
                        None => {
                            sqlx::query(
                                "UPDATE EpisodeQueue SET QueuePosition = ?
                                 WHERE EpisodeID = ? AND UserID = ?"
                            )
                            .bind(new_position)
                            .bind(episode_id)
                            .bind(user_id)
                            .execute(&mut *tx)
                            .await?;
                        }
                    }
                }

                tx.commit().await?;
                Ok(())
            }
        }
    }

    // Save episode - matches Python save_episode function
    pub async fn save_episode(&self, episode_id: i32, user_id: i32, is_youtube: bool) -> AppResult<()> {
        match self {
            DatabasePool::Postgres(pool) => {
                if is_youtube {
                    // Check if already saved
                    let existing = sqlx::query(
                        r#"SELECT "SaveID" FROM "SavedVideos" WHERE "VideoID" = $1 AND "UserID" = $2"#
                    )
                    .bind(episode_id)
                    .bind(user_id)
                    .fetch_optional(pool)
                    .await?;

                    if existing.is_none() {
                        sqlx::query(
                            r#"INSERT INTO "SavedVideos" ("VideoID", "UserID") VALUES ($1, $2)"#
                        )
                        .bind(episode_id)
                        .bind(user_id)
                        .execute(pool)
                        .await?;

                        // Update UserStats table - increment EpisodesSaved count
                        sqlx::query(r#"UPDATE "UserStats" SET episodessaved = episodessaved + 1 WHERE userid = $1"#)
                            .bind(user_id)
                            .execute(pool)
                            .await?;
                    }
                } else {
                    // Check if already saved
                    let existing = sqlx::query(
                        r#"SELECT saveid FROM "SavedEpisodes" WHERE episodeid = $1 AND userid = $2"#
                    )
                    .bind(episode_id)
                    .bind(user_id)
                    .fetch_optional(pool)
                    .await?;

                    if existing.is_none() {
                        sqlx::query(
                            r#"INSERT INTO "SavedEpisodes" (episodeid, userid) VALUES ($1, $2)"#
                        )
                        .bind(episode_id)
                        .bind(user_id)
                        .execute(pool)
                        .await?;

                        // Update UserStats table - increment EpisodesSaved count
                        sqlx::query(r#"UPDATE "UserStats" SET episodessaved = episodessaved + 1 WHERE userid = $1"#)
                            .bind(user_id)
                            .execute(pool)
                            .await?;
                    }
                }
                Ok(())
            }
            DatabasePool::MySQL(pool) => {
                if is_youtube {
                    // Check if already saved
                    let existing = sqlx::query(
                        "SELECT SaveID FROM SavedVideos WHERE VideoID = ? AND UserID = ?"
                    )
                    .bind(episode_id)
                    .bind(user_id)
                    .fetch_optional(pool)
                    .await?;

                    if existing.is_none() {
                        sqlx::query(
                            "INSERT INTO SavedVideos (VideoID, UserID) VALUES (?, ?)"
                        )
                        .bind(episode_id)
                        .bind(user_id)
                        .execute(pool)
                        .await?;

                        // Update UserStats table - increment EpisodesSaved count
                        sqlx::query("UPDATE UserStats SET EpisodesSaved = EpisodesSaved + 1 WHERE UserID = ?")
                            .bind(user_id)
                            .execute(pool)
                            .await?;
                    }
                } else {
                    // Check if already saved
                    let existing = sqlx::query(
                        "SELECT SaveID FROM SavedEpisodes WHERE EpisodeID = ? AND UserID = ?"
                    )
                    .bind(episode_id)
                    .bind(user_id)
                    .fetch_optional(pool)
                    .await?;

                    if existing.is_none() {
                        sqlx::query(
                            "INSERT INTO SavedEpisodes (EpisodeID, UserID) VALUES (?, ?)"
                        )
                        .bind(episode_id)
                        .bind(user_id)
                        .execute(pool)
                        .await?;

                        // Update UserStats table - increment EpisodesSaved count
                        sqlx::query("UPDATE UserStats SET EpisodesSaved = EpisodesSaved + 1 WHERE UserID = ?")
                            .bind(user_id)
                            .execute(pool)
                            .await?;
                    }
                }
                Ok(())
            }
        }
    }

    // Remove saved episode - matches Python remove_saved_episode function
    pub async fn remove_saved_episode(&self, episode_id: i32, user_id: i32, is_youtube: bool) -> AppResult<()> {
        match self {
            DatabasePool::Postgres(pool) => {
                if is_youtube {
                    let result = sqlx::query(
                        r#"DELETE FROM "SavedVideos" WHERE "VideoID" = $1 AND "UserID" = $2"#
                    )
                    .bind(episode_id)
                    .bind(user_id)
                    .execute(pool)
                    .await?;

                    // Only update UserStats if a row was actually deleted
                    if result.rows_affected() > 0 {
                        sqlx::query(r#"UPDATE "UserStats" SET episodessaved = episodessaved - 1 WHERE userid = $1"#)
                            .bind(user_id)
                            .execute(pool)
                            .await?;
                    }
                } else {
                    let result = sqlx::query(
                        r#"DELETE FROM "SavedEpisodes" WHERE episodeid = $1 AND userid = $2"#
                    )
                    .bind(episode_id)
                    .bind(user_id)
                    .execute(pool)
                    .await?;

                    // Only update UserStats if a row was actually deleted
                    if result.rows_affected() > 0 {
                        sqlx::query(r#"UPDATE "UserStats" SET episodessaved = episodessaved - 1 WHERE userid = $1"#)
                            .bind(user_id)
                            .execute(pool)
                            .await?;
                    }
                }
                Ok(())
            }
            DatabasePool::MySQL(pool) => {
                if is_youtube {
                    let result = sqlx::query(
                        "DELETE FROM SavedVideos WHERE VideoID = ? AND UserID = ?"
                    )
                    .bind(episode_id)
                    .bind(user_id)
                    .execute(pool)
                    .await?;

                    // Only update UserStats if a row was actually deleted
                    if result.rows_affected() > 0 {
                        sqlx::query("UPDATE UserStats SET EpisodesSaved = EpisodesSaved - 1 WHERE UserID = ?")
                            .bind(user_id)
                            .execute(pool)
                            .await?;
                    }
                } else {
                    let result = sqlx::query(
                        "DELETE FROM SavedEpisodes WHERE EpisodeID = ? AND UserID = ?"
                    )
                    .bind(episode_id)
                    .bind(user_id)
                    .execute(pool)
                    .await?;

                    // Only update UserStats if a row was actually deleted
                    if result.rows_affected() > 0 {
                        sqlx::query("UPDATE UserStats SET EpisodesSaved = EpisodesSaved - 1 WHERE UserID = ?")
                            .bind(user_id)
                            .execute(pool)
                            .await?;
                    }
                }
                Ok(())
            }
        }
    }

