    // Find episode ID by URL for user
    async fn find_episode_by_url(&self, user_id: i32, episode_url: &str) -> AppResult<Option<i32>> {
        match self {
            DatabasePool::Postgres(pool) => {
                let row = sqlx::query(r#"
                    SELECT e.episodeid 
                    FROM "Episodes" e 
                    JOIN "Podcasts" p ON e.feedid = p.feedid 
                    WHERE e.episodeurl = $1 AND p.userid = $2
                "#)
                    .bind(episode_url)
                    .bind(user_id)
                    .fetch_optional(pool)
                    .await?;
                
                if let Some(row) = row {
                    Ok(Some(row.try_get("episodeid")?))
                } else {
                    Ok(None)
                }
            }
            DatabasePool::MySQL(pool) => {
                let row = sqlx::query("
                    SELECT e.EpisodeID 
                    FROM Episodes e 
                    JOIN Podcasts p ON e.FeedID = p.FeedID 
                    WHERE e.EpisodeURL = ? AND p.UserID = ?
                ")
                    .bind(episode_url)
                    .bind(user_id)
                    .fetch_optional(pool)
                    .await?;
                
                if let Some(row) = row {
                    Ok(Some(row.try_get("EpisodeID")?))
                } else {
                    Ok(None)
                }
            }
        }
    }
    
