    // Get all shared episodes for a user
    pub async fn get_user_shared_episodes(&self, user_id: i32) -> AppResult<Vec<serde_json::Value>> {
        match self {
            DatabasePool::Postgres(pool) => {
                let rows = sqlx::query(r#"
                    SELECT
                        se.sharecode,
                        se.expirationdate,
                        COALESCE(e.episodetitle, ye.videotitle) AS episodetitle,
                        COALESCE(p.podcastname, yp.podcastname) AS podcastname
                    FROM "SharedEpisodes" se
                    LEFT JOIN "Episodes" e ON se.episodeid = e.episodeid
                    LEFT JOIN "Podcasts" p ON e.feedid = p.feedid AND p.userid = se.sharedby
                    LEFT JOIN "YouTubeVideos" ye ON se.episodeid = ye.videoid
                    LEFT JOIN "Podcasts" yp ON ye.podcastid = yp.podcastid
                    WHERE se.sharedby = $1
                    ORDER BY se.expirationdate DESC
                "#)
                .bind(user_id)
                .fetch_all(pool)
                .await?;

                let result = rows.iter().map(|row| {
                    let sharecode: String = row.try_get("sharecode").unwrap_or_default();
                    let expiration: chrono::NaiveDateTime = row.try_get("expirationdate").unwrap_or_else(|_| chrono::Utc::now().naive_utc());
                    let episode_title: String = row.try_get("episodetitle").unwrap_or_else(|_| "Unknown".to_string());
                    let podcast_name: String = row.try_get("podcastname").unwrap_or_else(|_| "Unknown".to_string());
                    serde_json::json!({
                        "share_code": sharecode,
                        "expiration_date": expiration.format("%Y-%m-%d %H:%M UTC").to_string(),
                        "episode_title": episode_title,
                        "podcast_name": podcast_name,
                    })
                }).collect();
                Ok(result)
            }
            DatabasePool::MySQL(pool) => {
                let rows = sqlx::query(
                    "SELECT
                        se.ShareCode AS sharecode,
                        se.ExpirationDate AS expirationdate,
                        COALESCE(e.EpisodeTitle, ye.VideoTitle) AS episodetitle,
                        COALESCE(p.PodcastName, yp.PodcastName) AS podcastname
                    FROM SharedEpisodes se
                    LEFT JOIN Episodes e ON se.EpisodeID = e.EpisodeID
                    LEFT JOIN Podcasts p ON e.FeedID = p.FeedID AND p.UserID = se.SharedBy
                    LEFT JOIN YouTubeVideos ye ON se.EpisodeID = ye.VideoID
                    LEFT JOIN Podcasts yp ON ye.PodcastID = yp.PodcastID
                    WHERE se.SharedBy = ?
                    ORDER BY se.ExpirationDate DESC"
                )
                .bind(user_id)
                .fetch_all(pool)
                .await?;

                let result = rows.iter().map(|row| {
                    let sharecode: String = row.try_get("sharecode").unwrap_or_default();
                    let expiration: chrono::NaiveDateTime = row.try_get("expirationdate").unwrap_or_else(|_| chrono::Utc::now().naive_utc());
                    let episode_title: String = row.try_get("episodetitle").unwrap_or_else(|_| "Unknown".to_string());
                    let podcast_name: String = row.try_get("podcastname").unwrap_or_else(|_| "Unknown".to_string());
                    serde_json::json!({
                        "share_code": sharecode,
                        "expiration_date": expiration.format("%Y-%m-%d %H:%M UTC").to_string(),
                        "episode_title": episode_title,
                        "podcast_name": podcast_name,
                    })
                }).collect();
                Ok(result)
            }
        }
    }

    // Delete a shared episode by share code (user must own it)
    pub async fn delete_user_shared_episode(&self, share_code: &str, user_id: i32) -> AppResult<bool> {
        match self {
            DatabasePool::Postgres(pool) => {
                let result = sqlx::query(r#"DELETE FROM "SharedEpisodes" WHERE sharecode = $1 AND sharedby = $2"#)
                    .bind(share_code)
                    .bind(user_id)
                    .execute(pool)
                    .await?;
                Ok(result.rows_affected() > 0)
            }
            DatabasePool::MySQL(pool) => {
                let result = sqlx::query("DELETE FROM SharedEpisodes WHERE ShareCode = ? AND SharedBy = ?")
                    .bind(share_code)
                    .bind(user_id)
                    .execute(pool)
                    .await?;
                Ok(result.rows_affected() > 0)
            }
        }
    }

    // Extend expiration of a shared episode by N days (user must own it)
    pub async fn extend_user_shared_episode(&self, share_code: &str, user_id: i32, days: i64) -> AppResult<bool> {
        match self {
            DatabasePool::Postgres(pool) => {
                let current: Option<chrono::NaiveDateTime> = sqlx::query_scalar(r#"
                    SELECT expirationdate FROM "SharedEpisodes" WHERE sharecode = $1 AND sharedby = $2
                "#)
                .bind(share_code)
                .bind(user_id)
                .fetch_optional(pool)
                .await?;

                let Some(current) = current else { return Ok(false); };
                let new_expiry = current + chrono::Duration::days(days);
                tracing::info!("Extending {} from {} to {} (+{} days)", share_code, current, new_expiry, days);

                sqlx::query(r#"
                    UPDATE "SharedEpisodes"
                    SET expirationdate = $1
                    WHERE sharecode = $2 AND sharedby = $3
                "#)
                .bind(new_expiry)
                .bind(share_code)
                .bind(user_id)
                .execute(pool)
                .await?;
                Ok(true)
            }
            DatabasePool::MySQL(pool) => {
                let result = sqlx::query(
                    "UPDATE SharedEpisodes SET ExpirationDate = DATE_ADD(ExpirationDate, INTERVAL ? DAY) WHERE ShareCode = ? AND SharedBy = ?"
                )
                .bind(days)
                .bind(share_code)
                .bind(user_id)
                .execute(pool)
                .await?;
                Ok(result.rows_affected() > 0)
            }
        }
    }

    pub async fn delete_playlist(&self, user_id: i32, playlist_id: i32) -> AppResult<()> {
        match self {
            DatabasePool::Postgres(pool) => {
                // Check if playlist exists and belongs to user
                let playlist = sqlx::query(
                    r#"SELECT issystemplaylist, userid FROM "Playlists" WHERE playlistid = $1"#
                )
                .bind(playlist_id)
                .fetch_optional(pool)
                .await?;

                let playlist = playlist.ok_or_else(|| AppError::not_found("Playlist not found"))?;

                let is_system: bool = playlist.try_get("issystemplaylist")?;
                let owner_id: i32 = playlist.try_get("userid")?;

                if is_system {
                    return Err(AppError::bad_request("Cannot delete system playlists"));
                }

                if owner_id != user_id {
                    return Err(AppError::forbidden("Unauthorized to delete this playlist"));
                }

                // Delete the playlist
                sqlx::query(r#"DELETE FROM "Playlists" WHERE playlistid = $1"#)
                    .bind(playlist_id)
                    .execute(pool)
                    .await?;

                Ok(())
            }
            DatabasePool::MySQL(pool) => {
                // Check if playlist exists and belongs to user
                let playlist = sqlx::query("SELECT IsSystemPlaylist, UserID FROM Playlists WHERE PlaylistID = ?")
                    .bind(playlist_id)
                    .fetch_optional(pool)
                    .await?;

                let playlist = playlist.ok_or_else(|| AppError::not_found("Playlist not found"))?;

                let is_system: i8 = playlist.try_get("IsSystemPlaylist")?;
                let owner_id: i32 = playlist.try_get("UserID")?;

                if is_system != 0 {
                    return Err(AppError::bad_request("Cannot delete system playlists"));
                }

                if owner_id != user_id {
                    return Err(AppError::forbidden("Unauthorized to delete this playlist"));
                }

                // Delete the playlist
                sqlx::query("DELETE FROM Playlists WHERE PlaylistID = ?")
                    .bind(playlist_id)
                    .execute(pool)
                    .await?;

                Ok(())
            }
        }
    }

    pub async fn update_playlist(&self, _config: &crate::config::Config, playlist_data: &crate::models::UpdatePlaylistRequest) -> AppResult<()> {
        let min_duration = playlist_data.min_duration.map(|d| d * 60);
        let max_duration = playlist_data.max_duration.map(|d| d * 60);

        match self {
            DatabasePool::Postgres(pool) => {
                // Verify ownership and not a system playlist
                let row = sqlx::query(
                    r#"SELECT issystemplaylist, userid FROM "Playlists" WHERE playlistid = $1"#
                )
                .bind(playlist_data.playlist_id)
                .fetch_optional(pool)
                .await?;

                let row = row.ok_or_else(|| AppError::not_found("Playlist not found"))?;
                if row.try_get::<bool, _>("issystemplaylist")? {
                    return Err(AppError::bad_request("Cannot edit system playlists"));
                }
                if row.try_get::<i32, _>("userid")? != playlist_data.user_id {
                    return Err(AppError::forbidden("Unauthorized to edit this playlist"));
                }

                let podcast_ids_array = playlist_data.podcast_ids.clone().unwrap_or_default();

                sqlx::query(r#"
                    UPDATE "Playlists" SET
                        name = $1,
                        description = $2,
                        podcastids = $3,
                        includeunplayed = $4,
                        includepartiallyplayed = $5,
                        includeplayed = $6,
                        minduration = $7,
                        maxduration = $8,
                        sortorder = $9,
                        groupbypodcast = $10,
                        maxepisodes = $11,
                        iconname = $12,
                        playprogressmin = $13,
                        playprogressmax = $14,
                        timefilterhours = $15
                    WHERE playlistid = $16
                "#)
                .bind(&playlist_data.name)
                .bind(&playlist_data.description)
                .bind(&podcast_ids_array)
                .bind(playlist_data.include_unplayed)
                .bind(playlist_data.include_partially_played)
                .bind(playlist_data.include_played)
                .bind(min_duration)
                .bind(max_duration)
                .bind(&playlist_data.sort_order)
                .bind(playlist_data.group_by_podcast)
                .bind(playlist_data.max_episodes)
                .bind(&playlist_data.icon_name)
                .bind(playlist_data.play_progress_min)
                .bind(playlist_data.play_progress_max)
                .bind(playlist_data.time_filter_hours)
                .bind(playlist_data.playlist_id)
                .execute(pool)
                .await?;

                self.update_playlist_contents(playlist_data.playlist_id).await?;
                Ok(())
            }
            DatabasePool::MySQL(pool) => {
                let row = sqlx::query(
                    "SELECT IsSystemPlaylist, UserID FROM Playlists WHERE PlaylistID = ?"
                )
                .bind(playlist_data.playlist_id)
                .fetch_optional(pool)
                .await?;

                let row = row.ok_or_else(|| AppError::not_found("Playlist not found"))?;
                let is_system: i8 = row.try_get("IsSystemPlaylist")?;
                if is_system != 0 {
                    return Err(AppError::bad_request("Cannot edit system playlists"));
                }
                if row.try_get::<i32, _>("UserID")? != playlist_data.user_id {
                    return Err(AppError::forbidden("Unauthorized to edit this playlist"));
                }

                let podcast_ids_json = serde_json::to_string(
                    &playlist_data.podcast_ids.clone().unwrap_or_default()
                )?;

                sqlx::query(r#"
                    UPDATE Playlists SET
                        Name = ?,
                        Description = ?,
                        PodcastIDs = ?,
                        IncludeUnplayed = ?,
                        IncludePartiallyPlayed = ?,
                        IncludePlayed = ?,
                        MinDuration = ?,
                        MaxDuration = ?,
                        SortOrder = ?,
                        GroupByPodcast = ?,
                        MaxEpisodes = ?,
                        IconName = ?,
                        PlayProgressMin = ?,
                        PlayProgressMax = ?,
                        TimeFilterHours = ?
                    WHERE PlaylistID = ?
                "#)
                .bind(&playlist_data.name)
                .bind(&playlist_data.description)
                .bind(&podcast_ids_json)
                .bind(playlist_data.include_unplayed)
                .bind(playlist_data.include_partially_played)
                .bind(playlist_data.include_played)
                .bind(min_duration)
                .bind(max_duration)
                .bind(&playlist_data.sort_order)
                .bind(playlist_data.group_by_podcast)
                .bind(playlist_data.max_episodes)
                .bind(&playlist_data.icon_name)
                .bind(playlist_data.play_progress_min)
                .bind(playlist_data.play_progress_max)
                .bind(playlist_data.time_filter_hours)
                .bind(playlist_data.playlist_id)
                .execute(pool)
                .await?;

                self.update_playlist_contents(playlist_data.playlist_id).await?;
                Ok(())
            }
        }
    }

